export function dependencies(graph: Record<string, string[]>, start: string): string[] {
  const visited = new Set<string>([start]);
  const pending = [start];
  while (pending.length > 0) {
    const current = pending.pop()!;
    const adjacent = Object.prototype.hasOwnProperty.call(graph, current) ? graph[current] : [];
    for (const item of adjacent ?? []) {
      if (!visited.has(item)) {
        visited.add(item);
        pending.push(item);
      }
    }
  }
  visited.delete(start);
  return [...visited].sort();
}

import test from "node:test";
import assert from "node:assert/strict";
import { dependencies } from "../src/graph.ts";
import { DocumentService } from "../src/service.ts";

test("transitive dependencies are unique, sorted, and exclude cycles back to the start", () => {
  const graph = {
    a: ["d", "b", "a", "b"],
    b: ["c", "d"],
    c: ["a", "c", "leaf"],
    d: ["c"],
    unreachable: ["other"],
  };
  const original = structuredClone(graph);
  for (const edges of Object.values(graph)) Object.freeze(edges);
  Object.freeze(graph);
  assert.deepEqual(dependencies(graph, "a"), ["b", "c", "d", "leaf"]);
  assert.deepEqual(new DocumentService().dependenciesFor(graph, "a"), ["b", "c", "d", "leaf"]);
  assert.deepEqual(graph, original);
});

test("missing entries are leaves, including IDs matching object prototype properties", () => {
  assert.deepEqual(dependencies({}, "missing"), []);
  assert.deepEqual(dependencies({}, "toString"), []);
  assert.deepEqual(dependencies({ a: ["toString", "constructor", "missing"] }, "a"),
    ["constructor", "missing", "toString"]);
  assert.deepEqual(dependencies({ a: [] }, "a"), []);
  assert.deepEqual(dependencies({ a: ["a"] }, "a"), []);
});

test("long dependency chains do not require recursive calls", () => {
  const graph = {};
  const expected = [];
  for (let i = 0; i < 20000; i++) {
    graph[String(i)] = [String(i + 1)];
    expected.push(String(i + 1));
  }
  assert.deepEqual(dependencies(graph, "0"), expected.sort());
});

